window.__BUNDLE__={"generatedAt":"2026-09-17T12:06:09.454893+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-09-10","archiveCutoff":"2021-09-18","addedToday":3,"addedThisRun":3,"fetchStats":{"hf":214,"arxiv":1313,"total":1527},"freshness":{"latestPaperDate":"2026-09-17","latestPublishedDate":"2026-09-17","latestBatchCount":266,"newInLast24h":312,"newInLast48h":1176},"historyTotal":14530,"topicCounts":{"Multi-Agent":2086,"Evaluation":7738,"Planning":1164,"Memory":297,"Code Agent":617,"Interpretability":539,"Agentic RAG":1159,"Agentic Search":1447,"RL for LLM":913,"Reasoning":4202,"Hallucination":838,"Post-Training":1741,"Alignment":1993,"World Model":196,"Tool Use":1133,"Agent Safety":2181,"Computer Use":246,"Reflection":547,"VLM Training":916,"LLM Training":1668,"Fine-tuning":2165,"Multimodal Agent":85,"Agent Framework":730,"Error Attribution":106,"Data Engine":304},"count":36,"recentTotal":1890,"archiveCount":0,"archiveTotal":12640,"sources":{"hf":44,"arxiv":1846,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"announceDate":"2026-09-17","title":"ScienceIDE: Turning World's Scientific Codebase into Agent Learnable Environments","source":"hf","id":"arxiv:2609.19134","url":"https://arxiv.org/abs/2609.19134","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.19134.pdf","upvotes":64,"authors":["Hejia Geng","Zesen Huang","Haoyang Li","Wenbin Li","Koutian Wu","Zihan Zhou","Yuanbo Pang","Weihao Liu","Zigong Xu","Zhiping Li","Zongzheng Zhang","Chuanfei Dong","Jiankai Sun","Tianzhe Zheng","Fengyu Xie","Yue Ma","Yueheng Shi","Tong Xie","Zonglin Di","Xianrong Liu","Qucheng Gao","Yimin Liu","Jiaming Pan","Sheng Huang","Xiao-Han Ma","Lanqing Yuan","Zhenlin Zhu","Ziang Liu","Ziyang Xu","Junkai Wang","Kangkai Liang","Jiayi Xian","Zehong Zhao","Liuwei Xu","Jingxu Xie","Peijin Zhang","Qiang Gao","Chengyi Xing","Zhe Zhao","Xi Wang","Yaopeng Xing","Xing Meng","Zhenfei Yin","Yingcheng Wu","Ling Yang"],"hfUrl":"https://huggingface.co/papers/2609.19134","tags":["LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"arxiv":"https://arxiv.org/abs/2609.19134","topics":["LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"date":"2026-09-17","abstract":"Scientific code repositories encode decades of human knowledge in executable models, methods, and tools. Yet fragmented toolchains, implicit domain conventions, and specialized correctness criteria make this knowledge difficult to convert into reliable learning experience-a challenge we call the scientific experience bottleneck. We introduce ScienceIDE, infrastructure for turning the world's scientific code into programmable environments for scientific agents. Guided by expert-defined scientific cases and acceptance criteria, agents transform repositories into executable environments that support task generation, execution, and scientific verification. These environments provide a shared foundation for supervised fine-tuning, reinforcement learning, and evaluation. Using verified interaction trajectories, we train PhAI-IDE-72B, PhAI-IDE-9B, and PhAI-IDE-4B. The model family shows gains i"},{"announceDate":"2026-09-17","title":"ProgramDistill: From Interactive Web Apps to Verifiable Reference-Guided SWE Tasks","source":"hf","id":"arxiv:2609.18805","url":"https://arxiv.org/abs/2609.18805","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18805.pdf","upvotes":42,"authors":["Jeonghye Kim","Minseon Kim","Young Jin Kim","Matheus Pereira","Marc-Alexandre Côté","Alessandro Sordoni","Xingdi Yuan","Zhengyan Shi"],"hfUrl":"https://huggingface.co/papers/2609.18805","tags":["Code Agent","Evaluation"],"arxiv":"https://arxiv.org/abs/2609.18805","topics":["Code Agent","Evaluation"],"date":"2026-09-17","abstract":"Coding agents are typically evaluated with desired behavior specified through issues or instructions. In practical web development, however, agents may need to infer behavior from working software and implement it in an incomplete application. We introduce ProgramDistill, a benchmark evaluating coding agents on features discovered through interaction with fully functional reference applications. We build ProgramDistill by factorizing applications into features of different granularities, each associated with replayable behaviors executable via its gold patch. Our pipeline, mine-craft-patch, discovers 1,975 replay-verified behaviors across 26 applications and constructs 4,063 tasks without human intervention. Across nine frontier coding agents, GPT-6 Astra and Claude Opus 5 achieve 49.2% and 28.8% success on cumulative workflows in full-application reconstruction. In partial-application r"},{"announceDate":"2026-09-17","title":"Agora: Git as Shared Memory for Collective AutoResearch","source":"hf","id":"arxiv:2609.18094","url":"https://arxiv.org/abs/2609.18094","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18094.pdf","upvotes":32,"authors":["Yifan Zhang","Yunheng Zou","Shaokun Zhang","Jian Hu","Hao Zhang","Binfeng Xu","Jan Kautz","Yi Dong"],"hfUrl":"https://huggingface.co/papers/2609.18094","tags":["LLM Training","Code Agent"],"arxiv":"https://arxiv.org/abs/2609.18094","topics":["LLM Training","Code Agent"],"date":"2026-09-17","abstract":"Autonomous research loops such as AutoResearch show that one coding agent can improve a training setup unattended. Run several of them and each session starts from scratch, so more agents tend to mean more duplicated search rather than more discovery. Agora is a shared memory for such agents: research is recorded as an append-only directed acyclic graph (DAG) stored in Git, so that every claim is a commit anyone can check out and rerun. Each result, insight, hypothesis, verification, and report is an immutable commit whose parent edges say what it builds on; a derived index exposes the frontier, the neglected branches, and the verification status of each claim, and a diversity-aware selection rule keeps the community from collapsing onto one leader. We describe the system and report its first sustained use: a run of nearly 12 days in which 13 language-model workers, with no assigned task"},{"announceDate":"2026-09-17","title":"EvolveTrade: Experience-Driven Policy Refinement for Self-Evolving LLM Trading Agents","source":"hf","id":"arxiv:2609.17632","url":"https://arxiv.org/abs/2609.17632","submittedDate":"2026-09-15","pdf":"https://arxiv.org/pdf/2609.17632.pdf","upvotes":28,"authors":["Sehee Kim","Yumin Choi","Minki Kang","Sung Ju Hwang"],"hfUrl":"https://huggingface.co/papers/2609.17632","tags":["Tool Use"],"arxiv":"https://arxiv.org/abs/2609.17632","topics":["Tool Use"],"date":"2026-09-17","abstract":"Large language model (LLM) trading agents can combine market data, news, and executable analysis, but their behavior is often controlled by static hand-written tool-use policies that are fixed before deployment. This limits their ability to adapt how they gather evidence, invoke tools, verify signals, and manage risk under changing market regimes. We introduce EvolveTrade, a self-evolving framework that treats the system prompt of a tool-using trading agent as a text-parameterized policy. After each update interval, a Policy Agent revises this policy using accumulated decision traces and realized portfolio feedback, while keeping the backbone LLM fixed. The updated policy is then used for the next batch of trading decisions, enabling the agent to refine its information-acquisition and portfolio-construction procedure over time. Experiments across multiple market regimes and two LLM backb"},{"announceDate":"2026-09-17","title":"Confidence Comes from Experience: Experiential Confidence Estimation from Reasoning to Agents","source":"arxiv","id":"arxiv:2609.17708","url":"https://arxiv.org/abs/2609.17708","submittedDate":"2026-09-15","pdf":"https://arxiv.org/pdf/2609.17708.pdf","upvotes":45,"authors":["Caiqi Zhang","Xiaochen Zhu","Chengzu Li","Yulong Chen","Dharshan Kumaran","Nigel Collier"],"hfUrl":"https://huggingface.co/papers/2609.17708","tags":["Reasoning","Evaluation","Reflection"],"arxiv":"https://arxiv.org/abs/2609.17708","topics":["Reasoning","Evaluation","Reflection"],"date":"2026-09-17","abstract":"Reliable confidence estimation is increasingly central to the trustworthy deployment of language models: a calibrated estimate of the probability that an output is correct decides what to ship, what to escalate, and what to retry. Existing confidence estimators, however, share one design premise: they only read the current inference process, either by introspecting on it, scoring its token probabilities, or resampling it. We argue that the current inference is not a sufficient basis for confidence. We propose XConf (eXperiential Confidence): estimating confidence together with the model's accumulated experience. The experience is stored as a record of the model's own graded past episodes, each holding the task, the model's reflection, its stated confidence, the outcome, and a lesson written once the grade arrived. Given a new task, XConf's Recall stage retrieves past episodes on similar "},{"announceDate":"2026-09-17","title":"Rethinking Critic Learning in PPO: Understanding and Mitigating Value Flattening","source":"arxiv","id":"arxiv:2609.18708","url":"https://arxiv.org/abs/2609.18708","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18708.pdf","upvotes":44,"authors":["Yizhuo Li","Jianhao Yan","Yun Luo","Zhi Wang","Futing Wang","Rong-Xi Tan","Kanghui Tian","Ganqu Cui","Ning Ding","Peilin Zhao","Yafu Li","Yu Cheng"],"hfUrl":"https://huggingface.co/papers/2609.18708","tags":["RL for LLM"],"arxiv":"https://arxiv.org/abs/2609.18708","topics":["RL for LLM"],"date":"2026-09-17","abstract":"In reinforcement learning for large language models, Proximal Policy Optimization (PPO) commonly uses a critic to estimate state values and reduce the variance of policy updates. However, we uncover a systematic failure mode in PPO critics, which we call Value Flattening: state values, estimated from multiple Monte Carlo continuations, change sharply across intermediate states while critic predictions remain comparatively flat. We further observe this phenomenon in a controlled FrozenLake environment and find that it becomes more pronounced as the state space grows. Our theoretical and empirical analyses relate Value Flattening to an implicit variance penalty in the critic loss and redundant updates from temporally correlated states with similar gradients. Motivated by these findings, we introduce SParse Proximal Policy Optimization (SP$^3$O), which applies the value loss to only a few w"},{"announceDate":"2026-09-17","title":"A Zeroth-Order Paradigm for LLM Preference Alignment","source":"arxiv","id":"arxiv:2609.19144","url":"https://arxiv.org/abs/2609.19144","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.19144.pdf","upvotes":21,"authors":["Peter Chen","Xi Chen","Wotao Yin","Tianyi Lin"],"hfUrl":"https://huggingface.co/papers/2609.19144","tags":["Post-Training","Alignment","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.19144","topics":["Post-Training","Alignment","Fine-tuning"],"date":"2026-09-17","abstract":"Direct preference alignment methods are widely used to align large language models (LLMs) with human preferences because of their computational and memory efficiency. However, likelihood displacement motivates alternative ways to extract information from preference pairs with small likelihood margins. In this paper, we propose and analyze Comparison-based Preference Optimization (ComPO), a zeroth-order alignment method based on comparison oracles. ComPO extracts directional information from these pairs without directly optimizing a differentiable preference loss on them. We establish a convergence guarantee for its basic offline scheme under smoothness, gradient sparsity, and compatibility between the oracle and a latent objective. We further introduce online ComPO, which retains the offline comparison mechanism and uses unlabeled policy generations for reverse-KL control relative to a r"},{"announceDate":"2026-09-17","title":"PANORAMA: Panoptic Grounded Captioning via Mask Proposal Selection","source":"arxiv","id":"arxiv:2609.19143","url":"https://arxiv.org/abs/2609.19143","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.19143.pdf","upvotes":8,"authors":["Sara Pieri","Evangelos Kazakos","Shizhe Chen","Josef Sivic","Cordelia Schmid"],"hfUrl":"https://huggingface.co/papers/2609.19143","tags":["VLM Training","Evaluation","Alignment"],"arxiv":"https://arxiv.org/abs/2609.19143","topics":["VLM Training","Evaluation","Alignment"],"date":"2026-09-17","abstract":"Intelligent systems that act in the world require image understanding that is both comprehensive and spatially grounded. Current vision-language models (VLMs) can generate fluent and detailed image captions, but reliably associating them with image pixels remains challenging. Existing methods that combine dense captioning with pixel-level grounding often produce either incomplete descriptions or inaccurate segmentation masks. We study this problem through panoptic grounded captioning, a task that requires a VLM to describe both foreground objects and background regions while grounding each referring phrase with pixel-level masks. We make three contributions. First, we introduce PanoCaps, a human-annotated benchmark constructed from panoptic segmentation datasets. It provides dense captions with near-complete pixel coverage and image-text alignments at the entity level, supporting both tr"},{"announceDate":"2026-09-17","title":"In-Context Robot Learning with VLM Agents","source":"arxiv","id":"arxiv:2609.19138","url":"https://arxiv.org/abs/2609.19138","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.19138.pdf","upvotes":5,"authors":["Dongzhou Cheng","Taoran Yi","Ye Fang","Xingwu Zhang","Fan Feng","Yixuan Li","Gengxiong Zhuang","Rongze Wang","Shuai Yang","Wei Song","Weizhi Xue","Minyan Wu","Jie Gui","Jiaqi Wang","Tong Wu"],"hfUrl":"https://huggingface.co/papers/2609.19138","tags":["VLM Training","Agent Framework"],"arxiv":"https://arxiv.org/abs/2609.19138","topics":["VLM Training","Agent Framework"],"date":"2026-09-17","abstract":"Enabling robots to adapt to unfamiliar environments as readily as humans remains a moonshot goal of embodied AI. No finite collection of demonstrations can cover every task and situation a robot will encounter, making the ability to learn from context at deployment essential for generalization. Such in-context learning (ICL), however, remains largely beyond the reach of existing robotic policies. The broad agentic capabilities of commercial vision-language models (VLMs), such as GPT-6 Astra, raise a compelling question: can these models learn from demonstrations, examples, and interaction feedback, then translate that information into executable and verifiable robot behavior from a new initial state without gradient updates or persistent changes to task-specific parameters? We introduce GPT-Policy, a general-agent framework for in-context robot learning. GPT-Policy integrates a context c"},{"announceDate":"2026-09-17","title":"Beyond Routine Compliance: Cunning Data Cultivates Safety Vigilance in Large Language Models","source":"arxiv","id":"arxiv:2609.18515","url":"https://arxiv.org/abs/2609.18515","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18515.pdf","upvotes":0,"authors":["Youjia Wang","Lin Xu","Yang Sun","Yuxiao Lu","Chengfang Fang","Jie Shi"],"tags":["Agent Safety","Reasoning","Planning","Evaluation","Alignment"],"arxiv":"https://arxiv.org/abs/2609.18515","topics":["Agent Safety","Reasoning","Planning","Evaluation","Alignment","Fine-tuning"],"date":"2026-09-17","abstract":"Safety alignment teaches large language models (LLMs) to recognize harmful requests and reject risky instructions. Yet aligned models can fail when harmful intent is concealed within seemingly benign contexts. Robust safety therefore requires both knowledge of safety boundaries and \\textbf{vigilance}: the ability to detect unusual premises, misleading reasoning, and latent risks beneath surface-level semantics. Vigilance requires models to scrutinize a request's underlying intent and assumptions before acting. To cultivate this capability, we introduce \\textbf{cunning questions}, which are not necessarily safety-related but contain misleading premises, atypical reasoning, or subtle inconsistencies. We hypothesize that learning to look beyond such reasoning traps can transfer to safety-critical scenarios. Experiments show that Cunning training improves robustness to out-of-distribution ja"},{"announceDate":"2026-09-17","title":"One Size Does Not Fit All! Dynamic Retriever and Generator Selection for RAG","source":"arxiv","id":"arxiv:2609.17709","url":"https://arxiv.org/abs/2609.17709","submittedDate":"2026-09-15","pdf":"https://arxiv.org/pdf/2609.17709.pdf","upvotes":0,"authors":["Neeraj Anand","Payel Santra","Partha Basuchowdhuri","Debasis Ganguly","Sumit Bhatia"],"tags":["Agentic RAG","Agentic Search","LLM Training","Reasoning","Evaluation"],"arxiv":"https://arxiv.org/abs/2609.17709","topics":["Agentic RAG","Agentic Search","LLM Training","Reasoning","Evaluation","Fine-tuning"],"date":"2026-09-17","abstract":"Retrieval-Augmented Generation (RAG) systems typically employ fixed retriever and generator configurations across queries, despite substantial differences in query complexity and information needs, leading to inefficient allocation of computational resources. While retrieval and generation adaptivity have been studied independently, their joint effect on end-to-end RAG performance remains underexplored. We systematically analyze how retriever and generator complexity interacts across factoid and multi-hop question answering (QA), including bridge and composition reasoning tasks. Our analysis shows that stronger retrieval generally yields larger gains than increased generation effort, but both exhibit diminishing and non-monotonic returns, indicating that higher-complexity configurations are not uniformly better across queries. Motivated by these findings, we introduce DRAG, a query-adapt"},{"announceDate":"2026-09-17","title":"Voice of Reason: Reinforcement Learning for Spoken Math","source":"arxiv","id":"arxiv:2609.18677","url":"https://arxiv.org/abs/2609.18677","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18677.pdf","upvotes":0,"authors":["Timothée Weisselberger","Edouard Graves","Alexandre Défossez"],"tags":["LLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.18677","topics":["LLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning","RL for LLM"],"date":"2026-09-17","abstract":"Speech language models enable richer spoken interactions between humans and machines than cascaded systems, allowing access to paralinguistic information and lower latency. However, their accuracy on mathematical reasoning benchmarks has lagged behind those of text models. Reinforcement learning (RL) with verifiable rewards has been instrumental in extending text models' capabilities for solving complex problems and limiting hallucinations. In this work, we explore applying RL to the GLM-4-Voice speech model (Zeng et al., 2024) to bridge the gap between textual and spoken mathematical problem solving. We first adapt the model to the domain using supervised fine-tuning on synthesized spoken question-answering data. We then show that, even without extra reasoning tokens, RL improves the accuracy on GSM8K beyond levels previously achieved for speech models only with supplementary reasoning "},{"announceDate":"2026-09-17","title":"AgenTeeth: A Model-Agnostic Framework for Suppressing Hallucination in Frozen Vision-Language Models on Dental X-Rays via Tool Evidence Injection","source":"arxiv","id":"arxiv:2609.17800","url":"https://arxiv.org/abs/2609.17800","submittedDate":"2026-09-15","pdf":"https://arxiv.org/pdf/2609.17800.pdf","upvotes":0,"authors":["Ahmed Rafid","Fariya Ahmed","Rumman Adib","Mehedi Ahamed","Ajwad Abrar","Tareque Mohmud Chowdhury"],"tags":["LLM Training","VLM Training","Tool Use","Reasoning","Hallucination"],"arxiv":"https://arxiv.org/abs/2609.17800","topics":["LLM Training","VLM Training","Tool Use","Reasoning","Hallucination","Fine-tuning"],"date":"2026-09-17","abstract":"Vision-language models (VLMs) remain largely unreliable on panoramic dental radiographs and can rely on learned anatomical priors rather than evidence in the image. This is particularly problematic for tooth localization and spatial reasoning, and fine-tuned dental VLMs can retain the same spatial biases. We present AgenTeeth, a model-agnostic, tool-augmented framework that grounds frozen VLMs using seven specialized dental vision experts. A question-aware orchestrator selects the relevant tools, whose detections are mapped to FDI tooth numbers or anatomical regions and returned as structured findings together with annotated image overlays. A fresh synthesis call then answers the question using this evidence, without fine-tuning the underlying VLM. On MMOral-OPG-Bench, AgenTeeth improves four backbone VLMs by 12.9-23.0 percentage points over their baselines. Our strongest configuration r"},{"announceDate":"2026-09-17","title":"Anchoring What Matters: A Dual-Level Learning Framework for Visually-Grounded Multimodal Reasoning","source":"arxiv","id":"arxiv:2609.18057","url":"https://arxiv.org/abs/2609.18057","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18057.pdf","upvotes":0,"authors":["Xinxin Song","Siyuan Li","Tingxiong Xiao","Jinli Suo"],"tags":["VLM Training","Reasoning","Memory","Evaluation","RL for LLM"],"arxiv":"https://arxiv.org/abs/2609.18057","topics":["VLM Training","Reasoning","Memory","Evaluation","RL for LLM"],"date":"2026-09-17","abstract":"Reinforcement learning with verifiable rewards (RLVR) has significantly improved the reasoning capabilities of large vision-language models (LVLMs). However, standard on-policy RLVR algorithms face a critical optimization bottleneck in preserving and reinforcing visually grounded reasoning behaviors: valuable visually-grounded reasoning trajectories are discarded after a single update, while uniform token advantage allocation prevents the model from reinforcing critical perception or reasoning steps. To bridge this gap, we propose PIVOT, a dual-level learning framework that anchors policy optimization around informative visual reasoning signals. Specifically, PIVOT introduces a self-calibrated experience replay mechanism, which selectively collects and replays visually-grounded historical experiences as stable reference anchors for policy optimization. Building upon this, we further desi"},{"announceDate":"2026-09-17","title":"WFM: Wiki Foundation Model for Complex Agentic Reasoning","source":"arxiv","id":"arxiv:2609.18182","url":"https://arxiv.org/abs/2609.18182","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18182.pdf","upvotes":0,"authors":["Junnan Dong","Linhao Luo","Senlei Zhang","Gong Chen","Taian Guo","Yifei Yu","Rong Tao","Tao Guo","Qian-Wen Zhang","Siyu An","Ruizhi Qiao","Xing Sun"],"tags":["Agentic RAG","Agentic Search","Reasoning","Memory","Evaluation"],"arxiv":"https://arxiv.org/abs/2609.18182","topics":["Agentic RAG","Agentic Search","Reasoning","Memory","Evaluation"],"date":"2026-09-17","abstract":"Real-world agents fundamentally require persistent non-parametric knowledge for dynamic reasoning, i.e., long-term memory and retrieval-augmented generation. While graphs have shown reliable advantages in providing structured evidence, the sparse graph representations naturally restrict machine readability and semantic density required for complex agentic workflows. Driven by this limitation, the entire industry is witnessing a paradigm shift from traditional sparse graphs to LLM Wiki, an agent-native knowledge representation that couples dense document contexts with markdown files containing multi-layered topological linkages. However, parameterizing such rich semantics is challenging to encode dense textual contexts using traditional sparse graph embeddings. Moreover, learning LLM Wiki with existing graph encoders could overwhelm distributed system overheads that hinder deployment in l"},{"announceDate":"2026-09-17","title":"EDCT-Bench: Uncovering Faithfulness Gaps in VLMs via Explanation-Driven Counterfactual Testing","source":"arxiv","id":"arxiv:2609.17953","url":"https://arxiv.org/abs/2609.17953","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.17953.pdf","upvotes":0,"authors":["Sihao Ding","Santosh Vasa","Aditi Ramadwar","Thomas Monninger"],"tags":["VLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.17953","topics":["VLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning"],"date":"2026-09-17","abstract":"Vision-Language Models (VLMs) can produce Natural Language Explanations (NLEs) that sound plausible yet remain inconsistent with the visual evidence they cite. We present Explanation-Driven Counterfactual Testing (EDCT), an intervention-based protocol that extracts visual concepts cited in a model's explanation, applies verified minimal edits to them, and tests whether the resulting answer and explanation remain consistent with the edited image. Using this protocol, we create EDCT-Bench, a comprehensive benchmark spanning three complementary domains: knowledge-intensive visual question answering (OK-VQA), safety-critical driving (DriveLM), and 3D spatial reasoning (3DSRBench). Across the evaluated VLMs, EDCT reveals substantial faithfulness gaps, with models frequently producing responses inconsistent with verified visual changes. Finally, our fine-tuning study suggests that EDCT-generat"},{"announceDate":"2026-09-17","title":"Knowledge-Graph Based Augmentation versus Retrieval Augmented Generation for Cultural-Related Question Answering","source":"arxiv","id":"arxiv:2609.18317","url":"https://arxiv.org/abs/2609.18317","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18317.pdf","upvotes":0,"authors":["Pablo Poulenard","Yannis Karmim","Valentin Barrière"],"tags":["Agentic RAG","Agentic Search","LLM Training","Evaluation","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.18317","topics":["Agentic RAG","Agentic Search","LLM Training","Evaluation","Fine-tuning"],"date":"2026-09-17","abstract":"Large language models (LLMs) suffer from a long-tail deficit: culturally specific facts, particularly those concerning underrepresented regions such as Latin America, appear too rarely in pretraining corpora to be reliably memorized. Retrieval-Augmented Generation (RAG) addresses this by grounding generation in external text, but structured alternatives such as Knowledge Graphs (KGs) offer tighter control over what enters the context, along with potential gains in explainability and updatability. We benchmark Graph-RAG against standard RAG on LatamQA, a culturally grounded multiple-choice dataset spanning eight thematic categories. The graphs are built end-to-end from Wikipedia articles with KGGen, a recent open-domain extractor, without manual curation in our main setting. G-Retriever is competitive with RAG and reduces the error of the base LLM by 72\\% with a standard KG and 78\\% with "},{"announceDate":"2026-09-17","title":"STRETCH the Boundaries: A Unified Self-Taught Framework for Progressive LLM Evolution","source":"arxiv","id":"arxiv:2609.18642","url":"https://arxiv.org/abs/2609.18642","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18642.pdf","upvotes":0,"authors":["Yajie Yu","Mark Lee","Yue Feng"],"tags":["Reasoning","Evaluation","Alignment","Reflection","RL for LLM"],"arxiv":"https://arxiv.org/abs/2609.18642","topics":["Reasoning","Evaluation","Alignment","Reflection","RL for LLM"],"date":"2026-09-17","abstract":"Large language models (LLMs) often suffer from capability stagnation in self-improvement training because fixed difficulty levels fail to adapt to their evolving proficiency. To address this issue, we propose STRETCH (Self-Taught Reasoning Evolution via Targeted CHallenge), a unified framework inspired by cognitive scaffolding theory. STRETCH introduces a dynamic Stretch Zone mechanism that continuously aligns question difficulty with the model's solving capability. Within a single parameter space, the model alternates between a Scaffolder that generates adaptive, boundary-pushing challenges and a Learner that that optimizes its solving trajectories through reinforcement learning. This dual-loop co-evolution effectively stabilizes training, mitigates reward hacking and promote progressive reasoning growth. Experiments on both negotiation and operation research benchmarks demonstrate that"},{"announceDate":"2026-09-17","title":"Code Consistency Preference Optimization Verification for Language Model Alignment","source":"arxiv","id":"arxiv:2609.19002","url":"https://arxiv.org/abs/2609.19002","submittedDate":"2026-07-18","pdf":"https://arxiv.org/pdf/2609.19002.pdf","upvotes":0,"authors":["Yunlong Tan","Mingqiao Mo","Hao Zhang"],"tags":["Post-Training","LLM Training","Reasoning","Alignment","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.19002","topics":["Post-Training","LLM Training","Reasoning","Alignment","Fine-tuning"],"date":"2026-09-17","abstract":"Execution-based verification enhances large language models' mathematical reasoning through computational soundness and dependency-aware filtering. However, prior preference optimization methods relying on Bradley-Terry reward models fail to capture the logical dependencies and execution consistency needed for scientific tasks. We propose a method that generates computationally sound solutions with dependency graphs for execution-consistent preference optimization. We first build a scientific reasoning dataset using UltraFeedback prompts, model generations, verification, and consistency results. Then we extract reasoning step expressions, prerequisites, and derivability relationships to construct dependency graphs and compute execution consistency scores. These scores are appended to each step, creating paired training data. Fine-tuning Llama-3-8B and DeepSeekMath-7B yields significant g"},{"announceDate":"2026-09-17","title":"Lumen: Parameter-Efficient Alignment of Pretrained Vision and Language Encoders for Zero-Shot Computational Pathology","source":"arxiv","id":"arxiv:2609.17868","url":"https://arxiv.org/abs/2609.17868","submittedDate":"2026-09-15","pdf":"https://arxiv.org/pdf/2609.17868.pdf","upvotes":0,"authors":["Kiarash Tajbakhsh","Abdelrahman Faqieh","Michael Jopiti","Javier Garcia-Baroja","Philipp Zens","Branislav Zagrapan","Yuri Tolkach","Martin D. Berger","Aurel Perren","Bastian Dislich","Inti Zlobec","Amjad Khan"],"tags":["LLM Training","VLM Training","Evaluation","Alignment","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.17868","topics":["LLM Training","VLM Training","Evaluation","Alignment","Fine-tuning"],"date":"2026-09-17","abstract":"Pathology vision-language models are commonly built by pretraining or fine-tuning large encoders on paired image-caption data. We asked whether a pathology vision-language model can instead be assembled by parameter-efficient alignment of frozen unimodal foundation models, leaving their pretrained representations untouched. Here we present Lumen, which aligns frozen Virchow2 and BioMedBERT backbones using rank-4 adapters and projection heads, training only 0.40% of the total parameters on the public QUILT-1M corpus. Across nine public zero-shot patch benchmarks, Lumen achieved the highest mean chance-corrected balanced accuracy, 0.546 versus 0.461 for the strongest baseline (paired difference 0.086, 95% CI 0.042-0.136). On lymph-node metastasis detection, Lumen reached an AUROC of 0.964 (95% CI 0.956-0.971) on 4,214 held-out internal slides and 0.955 (95% CI 0.942-0.966) on 2,368 slides "},{"announceDate":"2026-09-17","title":"WetRobo: A Reproducible Robot Kit for Coding Agents in Biological Laboratories","source":"arxiv","id":"arxiv:2609.18435","url":"https://arxiv.org/abs/2609.18435","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18435.pdf","upvotes":0,"authors":["Yuna Oikawa","Kei Endo","Takanori Uzawa","Yunzhe Zhang","Manan Anjaria","Lerrel Pinto","Sherry Yang","Koji Tsuda"],"tags":["LLM Training","VLM Training","Code Agent","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.18435","topics":["LLM Training","VLM Training","Code Agent","Fine-tuning"],"date":"2026-09-17","abstract":"Automating biological research requires general-purpose, reproducible robot systems that allow individual wet-lab researchers to delegate robot tasks without performing teleoperation or neural-network training. Vision-language-action policies have been proposed for general-purpose arms, but can lose performance when their operating environment changes. We therefore built WetRobo, a robot kit that can readily transfer between laboratories. It consists of one robot arm, laboratory equipment (an incubator, a reagent bottle with a cap, and a Petri dish), the existing code that moves the arm, teleoperation demonstrations of each task that we recorded, and a general AGENTS.md skill file. A biological experimentalist provides natural-language tasks without collecting local teleoperation training data or training a neural network. The coding agent observes the local laboratory and writes and exe"},{"announceDate":"2026-09-17","title":"REPAIR: Resolving Long-Tail Confusion in Scientific Retrievers via Fact-Verified Iterative Refinement","source":"arxiv","id":"arxiv:2609.18262","url":"https://arxiv.org/abs/2609.18262","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18262.pdf","upvotes":0,"authors":["Yerim Oh","Gunhee Kim"],"tags":["LLM Training","Hallucination","Evaluation","Reflection"],"arxiv":"https://arxiv.org/abs/2609.18262","topics":["LLM Training","Hallucination","Evaluation","Reflection"],"date":"2026-09-17","abstract":"Precise retrieval of scientific information is fundamentally constrained by long-tailed concepts and high fact-sensitivity of scientific corpora. These challenges often limit the effectiveness of dense retrievers and hallucination-prone LLM augmentation. To address this, we present REPAIR, a self-evolving data augmentation framework for scientific dense retrievers. REPAIR iteratively synthesizes training data to address knowledge gaps by cycling through diagnosis of long-tail concepts, API-guided evidence expansion, and differentiation via hard negative mining. This process effectively grounds retrieval in factual reality to resolve fine-grained distinctions. Extensive experiments demonstrate that REPAIR significantly outperforms 19 strong baselines on nine materials science and biomedical benchmarks. Our work highlights that diagnosing and factually augmenting data to long-tail deficits"},{"announceDate":"2026-09-17","title":"Contiguity, Not Importance: Budgeted Repair of Stale KV Caches After Document Edits","source":"arxiv","id":"arxiv:2609.17983","url":"https://arxiv.org/abs/2609.17983","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.17983.pdf","upvotes":0,"authors":["Mingyang Mao","Wyatt Mackey","Xiaomin Lin"],"tags":["Agentic RAG","Agentic Search","Memory","Evaluation"],"arxiv":"https://arxiv.org/abs/2609.17983","topics":["Agentic RAG","Agentic Search","Memory","Evaluation"],"date":"2026-09-17","abstract":"KV-cache reuse can reduce inference cost in retrieval-augmented generation and agentic systems, but cached contexts may become stale when retrieved knowledge, working memory, or user state is edited. Under causal self-attention, even a local edit can affect downstream KV states. A full re-prefill reliably restores consistency but is costly, whereas refreshing only the edited span can leave downstream dependencies stale. We formulate in-place repair as budgeted recomputation and compare training-free position-selection policies on a factual RAG benchmark with matched direct and derived edits. Across three model families, all policies repair direct cases, but derived cases clearly separate them. At the primary budget, a contiguous edit-local window recovers at least 0.94 of the post-edit answer margin and substantially outperforms attention-based, KV-deviation, and structural selectors. Me"},{"announceDate":"2026-09-17","title":"First Token Matters: Understanding Safety Collapse in Large Reasoning Models","source":"arxiv","id":"arxiv:2609.18471","url":"https://arxiv.org/abs/2609.18471","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18471.pdf","upvotes":0,"authors":["Yizheng Yang","Haining Yu","Yuechen Wang","Yikai Hou","Xing Fu","Jinbo Yang","Tianqing Zhu"],"tags":["Post-Training","Reasoning","Evaluation","Alignment"],"arxiv":"https://arxiv.org/abs/2609.18471","topics":["Post-Training","Reasoning","Evaluation","Alignment"],"date":"2026-09-17","abstract":"Large Reasoning Models (LRMs) exhibit strong problem-solving abilities, yet their safety alignment often degrades when handling harmful queries. Existing approaches to improving safety largely rely on additional training or preference optimization, while offering limited understanding of the internal mechanisms behind safety failures. In this work, we investigate this failure through a token-level positional analysis of refusal dynamics and identify a localized vulnerability at the onset of reasoning, which we term Onset Refusal Collapse (ORC). We find that the refusal-related signal of LRMs drops sharply at the first generated token under harmful queries, which is associated with unsafe response generation. Motivated by this finding, we propose SafeToken, a lightweight inference-time intervention that injects a learned continuous safety anchor precisely at reasoning onset. Despite updat"},{"announceDate":"2026-09-17","title":"Label-free steering: Compressing test-time reinforcement learning into bias-only subspaces","source":"arxiv","id":"arxiv:2609.18587","url":"https://arxiv.org/abs/2609.18587","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18587.pdf","upvotes":0,"authors":["Naveen Vakada","Mingyuan Li","Shaoxiong Ji"],"tags":["LLM Training","VLM Training","Reasoning","RL for LLM"],"arxiv":"https://arxiv.org/abs/2609.18587","topics":["LLM Training","VLM Training","Reasoning","RL for LLM"],"date":"2026-09-17","abstract":"Test-time reinforcement learning (TTRL) enables models to improve their reasoning without relying on labeled training data, but existing approaches typically optimize a large fraction of the model parameters. This raises a natural question: can effective test-time adaptation emerge when both the reward signal and the optimization space are severely restricted? We answer this question with label-free bias-only TTRL, which uses majority-vote pseudo-labels as rewards and optimizes only approximately 100K bias parameters while keeping the pretrained backbone frozen. On MATH-500, our approach reaches 76.67% accuracy, slightly exceeding our own labeled bias-steering reproduction while optimizing 76,000x fewer parameters than full-parameter TTRL. The same training procedure improves performance across vision-language and audio reasoning tasks, including MathVista, AI2D, LogicVista, and MMAU. We"},{"announceDate":"2026-09-17","title":"MiST: Mid-Training LLMs for Cybersecurity","source":"arxiv","id":"arxiv:2609.18496","url":"https://arxiv.org/abs/2609.18496","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18496.pdf","upvotes":0,"authors":["Oded Ovadia","Elad Ben Zaken","Elad Guttman","Orly Moreno Kadosh"],"tags":["LLM Training","Evaluation","Fine-tuning","Data Engine"],"arxiv":"https://arxiv.org/abs/2609.18496","topics":["LLM Training","Evaluation","Fine-tuning","Data Engine"],"date":"2026-09-17","abstract":"Cybersecurity combines high-stakes analysis with complex technical language, making it an impactful and challenging domain for LLMs. We present MiST (Mid-trained Security Transformer), a suite of 8B and 32B models that achieve strong performance on public cybersecurity benchmarks. We use mid-training as an intermediate adaptation stage between general pre-training and cybersecurity training. Rather than performing continual pre-training over large volumes of raw domain text, we curate a compact, expert-vetted seed corpus, and transform it into high-quality domain-specific synthetic training data. The final MiST checkpoints improve mean cybersecurity accuracy by +13.1 and +8.6 absolute percentage points over the corresponding Qwen baselines for 8B and 32B, respectively, corresponding to relative gains of +27.0% and +15.8%. Ablation results further show that these cybersecurity gains arise"},{"announceDate":"2026-09-17","title":"Scaling Articulated Rationales for MLLM-based Recommendation","source":"arxiv","id":"arxiv:2609.17639","url":"https://arxiv.org/abs/2609.17639","submittedDate":"2026-09-15","pdf":"https://arxiv.org/pdf/2609.17639.pdf","upvotes":0,"authors":["Haoke Xiao","Yueyang Liu","Yuhui Zhang","Xiang Chen","Yufei Liu","Jia Xu","Yalong Guan","Xiaolan Zhu","Xiaoyu Zhang","Shijun Wang","Shuang Yang","Zijie Meng","Zejian Zhang","Ruochen Yang","Xiangyu Wu","Tingting Gao","Han Li","Lantao Hu","Cheng Luo","Kun Gai"],"tags":["Post-Training","LLM Training","Evaluation","Data Engine"],"arxiv":"https://arxiv.org/abs/2609.17639","topics":["Post-Training","LLM Training","Evaluation","Data Engine"],"date":"2026-09-17","abstract":"Modern recommendation systems largely infer user preferences from implicit behaviors such as clicks, watch time, and negative feedback, but these signals reveal what users do rather than why they like or dislike content. This work studies articulated user rationales (AURs), i.e., users' natural-language explanations of their preferences, as a new class of polarity-aware and reason-level textual signals for recommendation. Despite their potential value, AURs are difficult to use in industrial systems because they are naturally sparse, often low-quality, and only cover a small fraction of items. We present SARA (Scaling Articulated Rationales), an industrial framework that turns sparse AURs into scalable recommendation signals. SARA first builds a data engine that elicits and curates AURs from 240M Kuaishou Live users, producing SARA-HQ, a quality-controlled and author-centric rationale da"},{"announceDate":"2026-09-17","title":"The Missing \"I Don't Know\": Why Three Reasoning-Reliability Findings Converge on Calibrated Abstention","source":"arxiv","id":"arxiv:2609.17686","url":"https://arxiv.org/abs/2609.17686","submittedDate":"2026-09-15","pdf":"https://arxiv.org/pdf/2609.17686.pdf","upvotes":0,"authors":["Srijith Ravikumar"],"tags":["Post-Training","Reasoning","Hallucination","Evaluation"],"arxiv":"https://arxiv.org/abs/2609.17686","topics":["Post-Training","Reasoning","Hallucination","Evaluation"],"date":"2026-09-17","abstract":"Three recent results describe what look like unrelated LLM reliability problems. Yin et al. (2026) show reasoning RL collapses tool-reliability representations. Suleymanov et al. (2026) show that under safety-constrained generation, large models rewrite flagged spans while small models truncate. Bastounis et al. (2024) prove any consistent-reasoning system without an implicit \"I don't know\" function must hallucinate infinitely often on broad problem classes. We argue these findings converge on a single intervention: calibrated abstention is what each independently identifies as the missing capability, even though the unavailability they document, a capability gap, a policy gap, and a recursion-theoretic gap, has a different source in each case. Honesty post-training has narrowed the gap in deployed models, but principled closure of the class Bastounis identifies requires a calibrated abs"},{"announceDate":"2026-09-17","title":"Look Less, Hear Better: Jointly Rewarded GRPO for Streaming ASR","source":"arxiv","id":"arxiv:2609.18333","url":"https://arxiv.org/abs/2609.18333","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18333.pdf","upvotes":0,"authors":["Xiuwen Zheng"],"tags":["Post-Training","LLM Training","Alignment","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.18333","topics":["Post-Training","LLM Training","Alignment","Fine-tuning"],"date":"2026-09-17","abstract":"Streaming automatic speech recognition (ASR) must be judged jointly on what it transcribes and on how quickly it commits each word. Delayed streams modeling (DSM) has become the dominant paradigm for streaming large audio-language models, exposing a structural delay $τ$ that bounds the decoder's lookahead. We show that $τ$ is a poor proxy for user-perceived latency, and that the alignment-based supervision of DSM leaves latency on the table: the same forced-aligned transcript is used at every $τ$, forcing the model to withhold words it could already commit. We introduce AWED, a word-level emission-delay metric defined relative to the acoustic end of each word, and post-train a DSM recognizer with GRPO under a reward that scores transcription accuracy and measured delay jointly. Trained at a single operating point ($τ=6$ frames), our model dominates both its supervised fine-tuning initial"},{"announceDate":"2026-09-17","title":"EviGen: Predictive Evidence Scaffolding for Verifiable Clinical Rationale Generation","source":"arxiv","id":"arxiv:2609.18852","url":"https://arxiv.org/abs/2609.18852","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18852.pdf","upvotes":0,"authors":["Fengnan Li","Heman Burre","Liwen Sun","Roshni Varma","Matthew M. Engelhard"],"tags":["Agentic RAG","Agentic Search","Reasoning","Hallucination"],"arxiv":"https://arxiv.org/abs/2609.18852","topics":["Agentic RAG","Agentic Search","Reasoning","Hallucination"],"date":"2026-09-17","abstract":"Longitudinal electronic health records (EHRs) capture years of patient history across notes, codes, labs, and procedures, and contain evidence needed to reason about likely clinical outcomes. However, comprehensive clinician review of these records is impractical, and LLM-based processing is costly and often unreliable, missing some relevant observations while hallucinating others. We therefore propose EviGen, a three-layer framework for verifiable clinical rationale generation that addresses these challenges. The first layer is a patient-conditioned retriever that uses learnable queries to find evidence predictive of, not just textually relevant to, a clinical outcome and ranks it by prediction attribution scores. The second layer is an LLM generator that consumes this ranked evidence as a scaffold to produce a clinical rationale grounded in the retrieved spans. The third layer is a pro"},{"announceDate":"2026-09-17","title":"From Pixels to Pairs: A Comprehensive Benchmark of LLM-Based Key-Value Extraction in Noisy Document Settings","source":"arxiv","id":"arxiv:2609.17538","url":"https://arxiv.org/abs/2609.17538","submittedDate":"2026-07-14","pdf":"https://arxiv.org/pdf/2609.17538.pdf","upvotes":0,"authors":["Zahra Anvari","Vassilis Athitsos"],"tags":["Reasoning","Hallucination","Evaluation","Alignment"],"arxiv":"https://arxiv.org/abs/2609.17538","topics":["Reasoning","Hallucination","Evaluation","Alignment"],"date":"2026-09-17","abstract":"Large language models (LLMs) are increasingly used for structured information extraction from documents, yet their behavior under realistic OCR noise remains poorly understood. We present a systematic benchmark of open-source instruction-tuned LLMs for key-value pair (KVP) extraction under both clean-text and noisy OCR conditions. We evaluate representative decoder-only models (Gemma, Mistral, Qwen2.5, LLaMA 3, and DeepSeek) on the FUNSD, CORD, and SROIE benchmarks using both Gold-text annotations and OCR outputs from PaddleOCR, EasyOCR, and Tesseract. A unified evaluation protocol isolates the effects of input quality, model design, and prompting under consistent conditions. The results show that modern LLMs act as strong semantic extractors when high-quality text is available, in some cases approaching supervised layout-aware systems. Under OCR noise, however, performance degrades subs"},{"announceDate":"2026-09-17","title":"Attention Dispersion as a Diagnostic Signal for Hallucination in Large Language Models","source":"arxiv","id":"arxiv:2609.18320","url":"https://arxiv.org/abs/2609.18320","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18320.pdf","upvotes":0,"authors":["Shardul P. More","Tanuja S. Pawar"],"tags":["Reasoning","Hallucination","Evaluation","Alignment"],"arxiv":"https://arxiv.org/abs/2609.18320","topics":["Reasoning","Hallucination","Evaluation","Alignment"],"date":"2026-09-17","abstract":"Large Language Models (LLMs) frequently exhibit hallucinations, presenting a major barrier to reliability in complex reasoning tasks. While traditional detection methods rely on output-based confidence metrics, these logits are often miscalibrated by modern alignment techniques. In this paper, we investigate the temporal volatility of internal attention mechanisms as an alternative diagnostic signal for hallucination that does not depend on output calibration. By introducing an unsupervised metric for attention dispersion, we show that epistemic uncertainty leaves a measurable trace within intermediate layers, where spikes in attention entropy are associated with reasoning breakdowns. We evaluate our approach on mathematical reasoning benchmarks (GSM8K and MATH-500) using the Qwen2.5 model family (1.5B and 3B parameters), finding statistically significant AUC improvements of up to +0.076"},{"announceDate":"2026-09-17","title":"SEA-LION-v4.8: A Technical Report","source":"arxiv","id":"arxiv:2609.18310","url":"https://arxiv.org/abs/2609.18310","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18310.pdf","upvotes":0,"authors":["Ahmed Mohammad Dabeer","Ahn Jeongmi","Anocha Sutaveephamochanon","Antonyrex Sajeban","Aulia Adila","Chan Hok Teng","Adwin","Cheng Zi Yi","Nicholas Zhuang Ziyi","Choa Hsueh Mei Esther","David Ong Tat-Wee","Evelyn Tan Chor Phin","Heng Cheng Peng","Jonathan","Lee Chwan Ren","Leong Wai Yi","Leong Wei Qi","Leslie Teo Eng Sipp","Liew Rachel","Limkonchotiwat Peerat","Montalan Jann Railey Estrada","Muhammad Ridzuan Bin Mokhtar","Nagarajan Karthik","Ng Boon Cheong","Raymond","Ngui Jian Gang","Nguyen Thanh Ngan","Tasawong Panuthep","Pereira Mark Gregory","Phang Shi Wei Benjamin","Poon Yip Hung","Joseph","Rengarajan Hamsawardhini","Siow Wei Kang Bryan","Tai Ngee Chia","Tan Choon Meng","Tan Le Min","Sheryl","Tan Siao Wei","Tan Yi Xian","Tee Jun Yun","Teng Kok Wai","Tjhi William Chandra","Tuchinda Pume","Wu Donghang","Yong Xianbin","Yosephine","Zhang Zhou"],"tags":["Post-Training","LLM Training","Reasoning","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.18310","topics":["Post-Training","LLM Training","Reasoning","Fine-tuning"],"date":"2026-09-17","abstract":"We introduce Nemotron-SEA-LION-v4.8, a family of Southeast Asian Languages in One Network (SEA-LION) built upon NVIDIA Nemotron 3. The family includes 30B-A3B and 120B-A12B models, with both continued-pretrained base checkpoints and post-trained variants. We adapt the models using Southeast Asian, reasoning, code, and multilingual parallel datasets, followed by post-training with supervised fine-tuning and online on-policy distillation. On SEA-HELM, the 30B-A3B model improves the overall SEA score from 46.06 to 51.57, while the 120B-A12B model improves from 49.30 to 63.44. The strongest gains are observed in instruction following, natural language reasoning, and natural language understanding across seven Southeast Asian languages."},{"announceDate":"2026-09-17","title":"Sim-to-Real Traffic Scene Understanding by Decoupling Semantics from Caption Generation with V-JEPA","source":"arxiv","id":"arxiv:2609.18562","url":"https://arxiv.org/abs/2609.18562","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18562.pdf","upvotes":0,"authors":["Nguyen Hoai Thuong Bui","Thanh Nguyen Vo","Trinh Tra Giang Nguyen","Ha Duc Bui"],"tags":["VLM Training","Reasoning","Hallucination","Evaluation"],"arxiv":"https://arxiv.org/abs/2609.18562","topics":["VLM Training","Reasoning","Hallucination","Evaluation"],"date":"2026-09-17","abstract":"Track 2 of the AI City Challenge 2026 requires both visual question answering (VQA) and traffic event description generation under a challenging synthetic-to real domain shift. Existing vision-language approaches often entangle semantic understanding with language generation, making them susceptible to hallucination and inconsistent reasoning across event phases. In this work, we propose a decoupled semantic understanding framework that first resolves predefined traffic questions into structured semantic facts and subsequently uses these facts to guide caption generation. A frozen V-JEPA encoder extracts predictive scene representations, while a lightweight Llama-based predictor produces answers for VQA queries. To improve reliability, we introduce a training-free structured refinement mechanism that exploits statistical priors, inter-question relationships, and temporal event consistenc"},{"announceDate":"2026-09-17","title":"Can MiniMax-H3 Reason About the Physical World? An Evaluation of Omni-Modal Generative Model","source":"arxiv","id":"arxiv:2609.18323","url":"https://arxiv.org/abs/2609.18323","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18323.pdf","upvotes":0,"authors":["Haoyu Zhao","Zihao Zhao","Tianyu Deng","Ziqin Xu","Zihao Zhang","Xudong Wang","Jinxiang Guo","Chen Gao","Ziyi Ye","Yeying Jin","Jiaxi Gu","Zuxuan Wu","Shuicheng Yan"],"tags":["Reasoning","Evaluation","Alignment","World Model"],"arxiv":"https://arxiv.org/abs/2609.18323","topics":["Reasoning","Evaluation","Alignment","World Model"],"date":"2026-09-17","abstract":"Recent Omni-Modal Generative Models (Omni-Models) have advanced content generation toward unified modeling of text, images, video, and audio. MiniMax-H3 exemplifies this transition by combining multimodal context understanding with joint audio-visual generation in a shared latent framework. Its unified architecture raises a fundamental question: Can multimodal alignment improve the model's world reasoning, and what new evaluation paradigms do omni-modal inputs enable? To investigate this question, this work introduces a comprehensive evaluation framework organized around four complementary dimensions of physical world reasoning. Unlike existing evaluation frameworks for video generation and world models, which are often constrained by limited input modalities and evaluation settings where prompts closely match the target video content, our evaluation is specifically designed to exploit t"},{"announceDate":"2026-09-17","title":"Exploring LLMs and RAG for Plausible and Explainable Material Prediction of Vehicle Components","source":"arxiv","id":"arxiv:2609.18437","url":"https://arxiv.org/abs/2609.18437","submittedDate":"2026-09-16","pdf":"https://arxiv.org/pdf/2609.18437.pdf","upvotes":0,"authors":["Frederik Wagner","Annerose Eichel","Sabine Schulte im Walde"],"tags":["Agentic RAG","Agentic Search","Evaluation","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.18437","topics":["Agentic RAG","Agentic Search","Evaluation","Fine-tuning"],"date":"2026-09-17","abstract":"In this work, we explore whether LLMs can accurately predict and explain plausible materials for vehicle components such as brake discs or fuel injectors without requiring extensive fine-tuning. We test and evaluate three approaches: a standard generative LLM baseline, a single-pass Retrieval-Augmented Generation (RAG) approach, and an iterative Chain-of-Verification (CoVe) variant. For retrieval, we rely on publicly available data using a domain-filtered Wikipedia corpus. Since no gold standard exists for this task, we develop a custom web-based annotation tool supporting crucial functions for structured domain expert evaluation. LLM-based generation substantially outperforms prior work, which is not further surpassed by the tested RAG approaches. Our results surface remaining challenges for RAG-based systems: hyperparameter optimization, the availability of high-quality, legally access"}],"archive":[],"latestPath":"data/latest.json"};
